/*
 * NeoPixel Color Cycle — rainbow animation on a WS2812B
 *
 * Wiring:
 *   DIN  -> D6
 *   VCC  -> 5V
 *   GND  -> GND
 *
 * The pixel smoothly cycles through the full rainbow.
 */

#include <Adafruit_NeoPixel.h>

#define LED_PIN    6
#define LED_COUNT  1   // one WS2812B pixel placed on the canvas

Adafruit_NeoPixel strip(LED_COUNT, LED_PIN, NEO_GRB + NEO_KHZ800);

void setup() {
  strip.begin();
  strip.show();            // turn everything off
  Serial.begin(115200);
  Serial.println("NeoPixel ready. Watch it cycle!");
}

void loop() {
  for (int hue = 0; hue < 256; hue += 2) {
    setAll(Wheel(hue));
    delay(20);
  }
}

/* Map a hue (0..255) to a rainbow colour — from the Adafruit examples */
long Wheel(int pos) {
  pos = 255 - pos;
  if (pos < 85) {
    return strip.Color(255 - pos * 3, 0, pos * 3);
  }
  if (pos < 170) {
    pos -= 85;
    return strip.Color(0, pos * 3, 255 - pos * 3);
  }
  pos -= 170;
  return strip.Color(pos * 3, 255 - pos * 3, 0);
}

/* Push one colour to the first (only) pixel */
void setAll(long color) {
  strip.setPixelColor(0, color);
  strip.show();
}
